     * A client's statement: every invoice across their projects with what is left to pay on each, and
     * the total they still owe, also grouped by job with a subtotal per job. Drafts are listed but not owed, as they have not been sent, nor are
     * void invoices, as they have been cancelled.
     */
    @Transactional(readOnly = true)
    public ClientStatementResponse statementForClient(Long clientId) {
        Client client = clients.findById(clientId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
        Map<Long, BigDecimal> paid = paidByInvoice(found);
        Map<Long, BigDecimal> credited = creditedByInvoice(found);
        Function<String, MoneyRule> rules = moneyRules();
        List<ClientStatementResponse.Line> lines = found.stream()
                .map(i -> ClientStatementResponse.Line.from(i, paid.getOrDefault(i.getId(), BigDecimal.ZERO),
                        credited.getOrDefault(i.getId(), BigDecimal.ZERO), rules.apply(i.getCurrency())))
                .toList();
        String home = settings.homeCurrency();
        MoneyRule homeRule = rules.apply(home);
        return ClientStatementResponse.from(client.getId(), client.getName(), client.getCurrency(), lines,
                accountEntries(clientId, found, rules), home, l -> l.issuedDate() == null ? Optional.empty()
                        : fxRates.convert(l.currency(), home, l.issuedDate(), l.amountDue()).map(homeRule::round));
    }

    /**
     * A client's financial summary as at today: the billed, paid and outstanding totals of their statement, and the
     * part of the outstanding left to pay on invoices whose due date has passed.
     */
    @Transactional(readOnly = true)
package net.officefloor.hq.app.invoice;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Comparator;

/**
 * One dated entry on a client's running account. An invoice is a charge; a payment, credit note or deposit is a
 * credit; a refund of unused credit is a charge again. The balance is what the client owes once this entry and every
 * one before it is counted (negative when the client is in credit). The invoice is the one the entry is for, if any,
 * and the purchase-order number is that invoice's, if it has one.
 */
public record StatementEntry(Kind kind, Long sourceId, Long invoiceId, LocalDate date, String description,
        BigDecimal charge, BigDecimal credit, BigDecimal balance, String poNumber) {

    /** What an entry records, in the order entries on the same day are listed. */
    public enum Kind {
        INVOICE, PAYMENT, CREDIT_NOTE, DEPOSIT, REFUND
    }

    /** Date order; on the same day charges come before what was paid against them, then by record id. */
    static final Comparator<StatementEntry> DATE_ORDER = Comparator.comparing(StatementEntry::date)
            .thenComparing(StatementEntry::kind)
            .thenComparing(StatementEntry::sourceId);

    static StatementEntry charge(Kind kind, Long sourceId, Long invoiceId, LocalDate date, String description,
            BigDecimal amount, String poNumber) {
        return new StatementEntry(kind, sourceId, invoiceId, date, description, amount.setScale(2), null, null,
                poNumber);
    }

    static StatementEntry credit(Kind kind, Long sourceId, Long invoiceId, LocalDate date, String description,
            BigDecimal amount, String poNumber) {
        return new StatementEntry(kind, sourceId, invoiceId, date, description, null, amount.setScale(2), null,
                poNumber);
    }

    /** What this entry adds to what the client owes. */
    BigDecimal change() {
        return charge != null ? charge : credit.negate();
    }

    StatementEntry withBalance(BigDecimal balance) {
        return new StatementEntry(kind, sourceId, invoiceId, date, description, charge, credit, balance, poNumber);
    }
}
}

/** A client's invoices across all their projects, also grouped by job, with the total they still owe. */
export interface ClientStatement {
  clientId: number;
  clientName: string;
  /** The client's currency; every figure on the statement is in it. */
  currency: CurrencyCode;
  invoices: StatementInvoice[];
  jobs: StatementJob[];
  /** The total invoiced on the client's sent invoices (drafts and void ones are left out). */
  invoiced: number;
  /** How much of what was invoiced has been paid. */
  paid: number;
  /** The grand total still owed: what was invoiced less what was paid. */
  outstanding: number;
  /** The tax across the client's sent invoices (drafts and void ones are left out). */
  tax: number;
  /** Invoices, payments, credit notes, deposits and refunds in date order, each with the running balance. */
  entries: StatementEntry[];
  /** The business's home currency. */
  homeCurrency: CurrencyCode;
  /** The total still owed converted into the home currency, each invoice at its issue-date rate; null without a rate. */
  homeOutstanding: number | null;
}

/** What a client owed as at the end of a chosen day (negative when in credit). */
export interface ClientBalanceAsOf {
  clientId: number;
  currency: CurrencyCode;
  asOf: string;
  balance: number;
}

/** A note that a client's statement was emailed: the address it went to and when. */
export interface StatementEmail {
  id: number;
  clientId: number;
  email: string;
  sentAt: string;
}

/** A client's statement for a date range: the balance owed at its start, the entries within it, and the balance owed at its end. */
export interface ClientStatementRange {
  clientId: number;
  currency: CurrencyCode;
  from: string;
  to: string;
  openingBalance: number;
  entries: StatementEntry[];
